create extension if not exists pgcrypto;
create table if not exists organizations(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,plan text not null default 'pilot',created_at timestamptz not null default now());
create table if not exists users(id uuid primary key default gen_random_uuid(),email text not null unique,display_name text,created_at timestamptz not null default now());
create table if not exists memberships(organization_id uuid not null references organizations(id) on delete cascade,user_id uuid not null references users(id) on delete cascade,role text not null default 'member',created_at timestamptz not null default now(),primary key(organization_id,user_id));
create table if not exists api_keys(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,key_hash text not null unique,label text not null,last_used_at timestamptz,revoked_at timestamptz,created_at timestamptz not null default now());
create table if not exists data_sources(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,provider text not null,name text not null,status text not null default 'connected',last_synced_at timestamptz,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists model_versions(id uuid primary key default gen_random_uuid(),name text not null,version text not null unique,status text not null default 'active',metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists intelligence_runs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,metric text not null,horizon_days integer not null,model_version text not null,input_snapshot jsonb not null,output jsonb not null,created_at timestamptz not null default now());
create table if not exists forecast_outcomes(id uuid primary key default gen_random_uuid(),intelligence_run_id uuid not null references intelligence_runs(id) on delete cascade,observed_value numeric,error numeric,evaluated_at timestamptz);
create table if not exists alerts(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,severity text not null,title text not null,detail text not null,status text not null default 'open',created_at timestamptz not null default now(),resolved_at timestamptz);
create table if not exists audit_logs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,actor_user_id uuid references users(id),action text not null,resource_type text,resource_id text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists idx_memberships_user on memberships(user_id);create index if not exists idx_runs_org_created on intelligence_runs(organization_id,created_at desc);create index if not exists idx_alerts_org_status on alerts(organization_id,status);create index if not exists idx_audit_org_created on audit_logs(organization_id,created_at desc);